#!/usr/bin/env python3
"""Emit default-namespace journald snapshot or verification JSON."""
import datetime
import hashlib
import json
import os
import re
import shutil
import subprocess
import sys
from decimal import Decimal
from pathlib import Path

SCHEMA_VERSION = 1
ENV = {"PATH": "/usr/sbin:/usr/bin:/sbin:/bin", "LC_ALL": "C", "LANG": "C"}
SIZE_RE = re.compile(r"^([0-9]+(?:\.[0-9]+)?)\s*([KMGTPE]?)(?:i?B)?$", re.I)
USAGE_RE = re.compile(r"take up\s+([0-9]+(?:\.[0-9]+)?)\s*([KMGTPE]?)B?\s+in the file system", re.I)
POWERS = {"": 0, "K": 1, "M": 2, "G": 3, "T": 4, "P": 5, "E": 6}
FOUR_GIB = 4 * 1024 ** 3


def emit(event):
    print(json.dumps(event, separators=(",", ":"), sort_keys=True), flush=True)


def executable(name):
    path = shutil.which(name, path=ENV["PATH"])
    if not path:
        raise RuntimeError(f"missing executable: {name}")
    return path


def run(command, timeout=30):
    return subprocess.run(command, check=False, capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=timeout, env=ENV)


def checked(command, timeout=30):
    result = run(command, timeout)
    if result.returncode != 0:
        detail = (result.stderr or result.stdout or "no diagnostic").strip()
        raise RuntimeError(f"command rc={result.returncode}: {detail[:240]}")
    return result


def read_id(path, pattern):
    value = Path(path).read_text(encoding="ascii").strip().lower()
    if not re.fullmatch(pattern, value):
        raise ValueError(f"invalid identity in {path}")
    return value


def parse_config(text):
    section = None
    values = {}
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith(("#", ";")):
            continue
        if line.startswith("[") and line.endswith("]"):
            section = line[1:-1]
        elif section == "Journal" and "=" in line:
            key, value = line.split("=", 1)
            values[key.strip()] = value.strip()
    return values


def parse_size(value):
    match = SIZE_RE.fullmatch(value.strip())
    if not match:
        raise ValueError(f"unsupported size: {value!r}")
    return int(Decimal(match.group(1)) * (1024 ** POWERS[match.group(2).upper()]))


def budget(config, key, filesystem_total, default_percent):
    value = config.get(key, "").strip()
    if value:
        return parse_size(value)
    return min(filesystem_total * default_percent // 100, FOUR_GIB)


def properties(unit):
    names = "ActiveState,SubState,Result,ExecMainCode,ExecMainStatus,NRestarts"
    result = checked([executable("systemctl"), "show", unit, "--no-pager", "--property=" + names])
    values = {}
    for line in result.stdout.splitlines():
        key, separator, value = line.partition("=")
        if separator:
            values[key] = value
    return values


def context():
    machine_id = read_id("/etc/machine-id", r"[0-9a-f]{32}")
    boot_id = read_id("/proc/sys/kernel/random/boot_id", r"[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}")
    analyze = executable("systemd-analyze")
    config_result = checked([analyze, "--no-pager", "cat-config", "systemd/journald.conf"])
    config_text = config_result.stdout
    config = parse_config(config_text)
    storage_setting = (config.get("Storage", "") or "auto").lower()
    if storage_setting not in {"auto", "persistent", "volatile", "none"}:
        raise ValueError(f"unsupported Storage setting: {storage_setting}")
    if storage_setting == "none":
        return machine_id, boot_id, config_text, config, storage_setting, "none", None
    if storage_setting == "persistent" or (storage_setting == "auto" and Path("/var/log/journal").is_dir()):
        scope, root = "persistent", Path("/var/log/journal")
    else:
        scope, root = "volatile", Path("/run/log/journal")
    directory = root / machine_id
    if not directory.is_dir():
        raise FileNotFoundError(f"journal directory missing: {directory}")
    return machine_id, boot_id, config_text, config, storage_setting, scope, directory


def allocated(path):
    return path.stat().st_blocks * 512


def snapshot(base, config, storage_setting, scope, directory):
    if scope == "none":
        base.update(record_type="snapshot", collector_status="ok", storage_setting=storage_setting, storage_scope=scope)
        return base
    journal_files = [path for path in directory.iterdir() if path.is_file()]
    active = [path for path in journal_files if path.name.endswith(".journal") and "@" not in path.name]
    archived = [path for path in journal_files if path.name.endswith(".journal") and "@" in path.name]
    unclean = [path for path in journal_files if path.name.endswith(".journal~")]
    file_system = os.statvfs(directory)
    fragment = file_system.f_frsize or file_system.f_bsize
    filesystem_total = fragment * file_system.f_blocks
    filesystem_free = fragment * file_system.f_bavail
    max_key = "SystemMaxUse" if scope == "persistent" else "RuntimeMaxUse"
    keep_key = "SystemKeepFree" if scope == "persistent" else "RuntimeKeepFree"
    usage_result = checked([executable("journalctl"), f"--directory={directory}", "--disk-usage", "--no-pager"])
    diagnostic = (usage_result.stdout + "\n" + usage_result.stderr).strip()
    match = USAGE_RE.search(diagnostic)
    if not match:
        raise ValueError(f"unrecognized disk-usage output: {diagnostic[:240]}")
    latest = checked([executable("journalctl"), f"--directory={directory}", "--no-pager", "-n", "1", "--output=json"])
    latest_line = next((line for line in latest.stdout.splitlines() if line.strip()), None)
    latest_event = json.loads(latest_line) if latest_line else {}
    service = properties("systemd-journald.service")
    flush = properties("systemd-journal-flush.service")
    base.update({
        "record_type": "snapshot", "collector_status": "ok", "storage_setting": storage_setting,
        "storage_scope": scope, "journal_directory": str(directory),
        "active_state": service.get("ActiveState"), "sub_state": service.get("SubState"),
        "service_result": service.get("Result"), "service_exec_main_status": service.get("ExecMainStatus"),
        "service_n_restarts": service.get("NRestarts"), "flush_active_state": flush.get("ActiveState"),
        "flush_result": flush.get("Result"), "active_file_count": len(active),
        "archived_file_count": len(archived), "unclean_file_count": len(unclean),
        "active_allocated_bytes": sum(allocated(path) for path in active),
        "archived_allocated_bytes": sum(allocated(path) for path in archived),
        "unclean_allocated_bytes": sum(allocated(path) for path in unclean),
        "journal_usage_bytes": parse_size(match.group(1) + match.group(2)),
        "journal_max_use_bytes": budget(config, max_key, filesystem_total, 10),
        "journal_keep_free_bytes": budget(config, keep_key, filesystem_total, 15),
        "filesystem_total_bytes": filesystem_total, "filesystem_free_bytes": filesystem_free,
        "latest_entry_seen": 1 if latest_event else 0, "latest_entry_cursor": latest_event.get("__CURSOR"),
        "latest_entry_boot_id": latest_event.get("_BOOT_ID"),
    })
    return base


def verify(base, storage_setting, scope, directory):
    base.update(record_type="verify", storage_setting=storage_setting, storage_scope=scope)
    if scope == "none":
        base.update(collector_status="ok", verify_status="not_applicable", verify_return_code=0, verified_file_count=0)
        return base
    result = run([executable("journalctl"), f"--directory={directory}", "--verify", "--no-pager"], timeout=900)
    diagnostic = (result.stdout + "\n" + result.stderr).strip()
    base.update({
        "collector_status": "ok", "journal_directory": str(directory),
        "verify_status": "ok" if result.returncode == 0 else "failed",
        "verify_return_code": result.returncode,
        "verified_file_count": sum(1 for path in directory.iterdir() if path.is_file() and path.name.endswith((".journal", ".journal~"))),
        "verify_diagnostic_sha256": hashlib.sha256(diagnostic.encode("utf-8")).hexdigest(),
        "verify_diagnostic": diagnostic[:512],
    })
    return base


def main():
    mode = sys.argv[1] if len(sys.argv) == 2 else "snapshot"
    now = datetime.datetime.now(datetime.timezone.utc)
    base = {"schema_version": SCHEMA_VERSION, "sample_epoch": int(now.timestamp()), "event_time": now.strftime("%Y-%m-%dT%H:%M:%SZ")}
    try:
        if mode not in {"snapshot", "verify"}:
            raise ValueError("mode must be snapshot or verify")
        machine_id, boot_id, config_text, config, storage_setting, scope, directory = context()
        base.update(machine_id=machine_id, boot_id=boot_id, journald_config_sha256=hashlib.sha256(config_text.encode("utf-8")).hexdigest())
        event = snapshot(base, config, storage_setting, scope, directory) if mode == "snapshot" else verify(base, storage_setting, scope, directory)
        emit(event)
        return 0
    except Exception as error:
        base.update(record_type=mode, collector_status="error", error_class=type(error).__name__, error_reason=str(error)[:512])
        emit(base)
        print(f"journald health {mode} failed: {type(error).__name__}: {error}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
